import subprocess,os,select,signal,json,http.client,hashlib,time
from pathlib import Path
class Server:
 def __init__(self,data,fault=''):
  self.data=Path(data);self.data.mkdir(parents=True,exist_ok=True)
  self.tag=str(time.time_ns());self.err=(self.data/('server-'+self.tag+'.stderr')).open('w')
  env={**os.environ,'DEPOT_LISTEN':'127.0.0.1:0','DEPOT_DATA':str(self.data),'DEPOT_FAULT':fault}
  self.p=subprocess.Popen(['target/debug/depot-server'],env=env,stdout=subprocess.PIPE,stderr=self.err,text=True)
  try:
   assert select.select([self.p.stdout],[],[],10)[0],'readiness timeout'
   self.line=self.p.stdout.readline();self.addr=self.line.strip().split()[-1]
   self.base='http://'+self.addr;self.host,self.port=self.addr.rsplit(':',1)
   assert self.request('GET','/health')[0]==200
  except BaseException:self.stop();raise
 def request(self,method,path,body=None,headers=None):
  c=http.client.HTTPConnection(self.host,int(self.port),timeout=10)
  try:
   c.request(method,path,body,headers or {});r=c.getresponse();data=r.read();return r.status,dict(r.getheaders()),json.loads(data) if data else None
  finally:c.close()
 def json(self,method,path,obj,status):
  r=self.request(method,path,json.dumps(obj),{'Content-Type':'application/json'});assert r[0]==status,r;return r[2]
 def put(self,path,file,status=201):
  file=Path(file);c=http.client.HTTPConnection(self.host,int(self.port),timeout=20)
  try:
   c.putrequest('PUT',path);c.putheader('Content-Length',file.stat().st_size);c.putheader('Content-Type','application/octet-stream');c.endheaders()
   with file.open('rb') as stream:
    while block:=stream.read(65536):c.send(block)
   r=c.getresponse();body=r.read();assert r.status==status,(r.status,body);return json.loads(body)
  finally:c.close()
 def download(self,path,expected):
  c=http.client.HTTPConnection(self.host,int(self.port),timeout=20)
  try:
   c.request('GET',path+'/download');r=c.getresponse();assert r.status==200,r.status
   h=hashlib.sha256();size=0
   while block:=r.read(65536):h.update(block);size+=len(block)
   assert size==expected['size'],(size,expected)
   assert h.hexdigest()==expected['sha256'],(h.hexdigest(),expected)
   assert int(r.getheader('Content-Length'))==size
   assert r.getheader('ETag')=='"'+h.hexdigest()+'"',r.getheader('ETag')
   return {'size':size,'sha256':h.hexdigest(),'etag':r.getheader('ETag')}
  finally:c.close()
 def stop(self):
  if not hasattr(self,'p'):return
  if self.p.poll() is None:
   self.p.send_signal(signal.SIGINT)
   try:self.p.wait(timeout=5)
   except subprocess.TimeoutExpired:self.p.kill();self.p.wait(timeout=5);raise AssertionError('graceful shutdown deadline')
  rest=self.p.stdout.read();(self.data/('server-'+self.tag+'.stdout')).write_text(getattr(self,'line','')+rest);self.p.stdout.close();self.err.close()
 def __enter__(self):return self
 def __exit__(self,*_):self.stop()
def identity(file):
 h=hashlib.sha256();size=0
 with Path(file).open('rb') as s:
  while b:=s.read(65536):h.update(b);size+=len(b)
 return {'size':size,'sha256':h.hexdigest()}
def artifact(repo,name,version):return '/api/repos/'+repo+'/artifacts/'+name+'/'+version
